import { ComponentProps } from 'react';

export type CardElementProps = ComponentProps<'div'>;

export const cardVariantColors = [
  'neutral',
  'brand',
  'creative',
  'cloudy',
  'fresh',
  'healthy',
  'friendly',
  'joyful',
  'warm',
  'plain',
  'excited',
] as const;
export const cardVariantIntensity = ['clear', 'strong', 'weak'] as const;

export type CardColorVariant = (typeof cardVariantColors)[number];
export type CardIntensityVariant = (typeof cardVariantIntensity)[number];

export type CardProps = React.PropsWithoutRef<CardElementProps> & {
  elevation?: boolean;
  color?: CardColorVariant;
  intensity?: CardIntensityVariant;
};
