import React, { forwardRef } from 'react';

import { Check } from '@hexa-ui/icons';
import * as Checkbox from '@radix-ui/react-checkbox';
import clsx from 'clsx';

import { Icon } from '../../Icon';
import { chipContentStyle } from '../Chip.css';
import { checkmarkStyle, getSelectableChipStyle } from './Selectable.css';
import { SelectableChipProps } from './Selectable.types';

export const Selectable = forwardRef<HTMLButtonElement, SelectableChipProps>(
  (
    { label, disabled = false, icon, className, ...rest }: SelectableChipProps,
    ref,
  ) => {
    const styles = getSelectableChipStyle({ hasIcon: !!icon });

    return (
      <Checkbox.Root
        className={clsx(styles, className)}
        disabled={disabled}
        ref={ref}
        {...rest}
      >
        {icon && <Icon icon={icon} size="small" />}
        <div className={chipContentStyle}>
          {label}
          <Checkbox.Indicator className={checkmarkStyle}>
            <Icon icon={Check} size="small" />
          </Checkbox.Indicator>
        </div>
      </Checkbox.Root>
    );
  },
);

Selectable.displayName = 'Selectable';
