import { ComponentProps } from 'react';

export const avatarSizeOptions = ['tiny', 'small', 'medium', 'large'] as const;
export const avatarVariantOptions = ['initials', 'icon', 'image'] as const;

type Variant = (typeof avatarVariantOptions)[number];
type Size = (typeof avatarSizeOptions)[number];

export type AvatarElementProps = ComponentProps<'div'>;

type BaseAvatarProps = React.PropsWithoutRef<AvatarElementProps> & {
  variant?: Variant;
  size?: Size;
  initialsLetters?: string;
  disabled?: boolean;
};

type ImageVariantProps = BaseAvatarProps & {
  variant?: 'image';
  imageSrc: string;
  alt?: string;
};

type InitialsVariantProps = BaseAvatarProps & {
  variant?: 'initials';
  initialsLetters: string;
  imageSrc?: string;
  alt?: string;
};

type IconVariantProps = BaseAvatarProps & {
  variant?: 'icon';
  imageSrc?: string;
  alt?: string;
};

export type AvatarProps =
  | ImageVariantProps
  | InitialsVariantProps
  | IconVariantProps;
