import React from 'react';

import * as RadixTooltip from '@radix-ui/react-tooltip';
import clsx from 'clsx';

import { getArrowStyles, getContentStyles, getTextStyles } from './Tooltip.css';
import { TooltipProps } from './Tooltip.types';

export const Tooltip = ({
  position = 'bottom',
  className,
  children,
  open,
  onOpenChange,
  defaultOpen,
  content,
  ...rest
}: TooltipProps) => {
  const styles = getContentStyles({ position });

  return (
    <RadixTooltip.Provider>
      <RadixTooltip.Root
        delayDuration={300}
        open={open}
        onOpenChange={onOpenChange}
        defaultOpen={defaultOpen}
      >
        <RadixTooltip.Trigger asChild>{children}</RadixTooltip.Trigger>
        <RadixTooltip.Content
          className={clsx(styles, className)}
          sideOffset={8}
          arrowPadding={0}
          collisionPadding={8}
          side={position}
          {...rest}
        >
          <div className={clsx(getTextStyles)}>{content}</div>
          <RadixTooltip.Arrow className={clsx(getArrowStyles)} />
        </RadixTooltip.Content>
      </RadixTooltip.Root>
    </RadixTooltip.Provider>
  );
};
