import React, { forwardRef, useMemo } from 'react';

import { Check } from '@hexa-ui/icons';
import clsx from 'clsx';

import { logError } from '../../utils/helpers';
import { Icon } from '../Icon';
import { LoadingSpinner, loadingSpinnerSizeOptions } from '../LoadingSpinner';
import { getStyles, iconContainerStyles } from './Button.css';
import { ButtonProps } from './Button.types';

export const colorOptions = ['default', 'inverted'] as const;
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      children,
      size = 'medium',
      variant = 'primary',
      float = false,
      loading = false,
      iconPosition = 'leading',
      icon,
      disabled = false,
      selected = false,
      ...rest
    }: ButtonProps,
    ref,
  ) => {
    const hasIcon = Boolean(icon);
    const styles = getStyles({
      size,
      variant,
      float,
      hasIcon,
      iconPosition,
      selected,
      loading,
      disabled,
    });
    const iconContainer = iconContainerStyles({
      iconPosition,
      size,
      disabled,
      variant,
    });

    logError(
      loading && disabled,
      `Invalid combination: loading and disabled can't be true at the same time`,
    );

    logError(
      loading && selected,
      `Invalid combination: loading and selected can't be true at the same time`,
    );

    logError(
      disabled && selected,
      `Invalid combination: disabled and selected can't be true at the same time`,
    );

    logError(
      (loading || selected) &&
        !(variant === 'primary' || variant === 'secondary'),
      `Invalid combination: loading or selected can't be true when variant is ${variant}`,
    );

    logError(
      hasIcon && variant === 'destructive',
      `Invalid combination: can't use icon when variant is destructive`,
    );

    logError(
      float && variant === 'tertiary',
      `Invalid combination: can't use float when variant is tertiary`,
    );

    logError(
      hasIcon && selected,
      `Invalid combination: can't use icon when selected is true`,
    );

    const loadingProps = useMemo(() => {
      let color: (typeof colorOptions)[number] = 'default';

      if (variant === 'primary') {
        color = 'inverted';
      }

      return {
        color: color,
        size: size,
      };
    }, [variant, size]);

    const iconSizeProps = useMemo(() => {
      let iconSize: (typeof loadingSpinnerSizeOptions)[number] = 'large';

      if (size === 'medium' || size === 'small') {
        iconSize = 'small';
      }

      if (size === 'large') {
        iconSize = 'medium';
      }

      return {
        size: iconSize,
      };
    }, [size]);

    const selectedIconSizeProps = useMemo(() => {
      let iconSize: (typeof loadingSpinnerSizeOptions)[number] = 'small';

      if (size === 'large' || size === 'medium') {
        iconSize = 'medium';
      }

      return {
        size: iconSize,
      };
    }, [size]);

    const renderButton = () => {
      if (loading) {
        return <LoadingSpinner {...loadingProps} />;
      }

      if (selected) {
        return <Icon {...selectedIconSizeProps} icon={Check} />;
      }

      return children;
    };

    return (
      <button
        className={clsx(styles, className)}
        disabled={disabled}
        type="button"
        data-testid="buttonComponent"
        ref={ref}
        {...rest}
      >
        {iconPosition === 'leading' && icon && (
          <Icon
            className={clsx(iconContainer)}
            {...iconSizeProps}
            icon={icon}
          />
        )}
        {renderButton()}
        {iconPosition === 'trailing' && icon && (
          <Icon
            className={clsx(iconContainer)}
            {...iconSizeProps}
            icon={icon}
          />
        )}
      </button>
    );
  },
);

Button.displayName = 'Button';
