import React, { createContext, useContext, useMemo } from 'react';

import { ChevronDown } from '@hexa-ui/icons';
import * as AccordionPrimitive from '@radix-ui/react-accordion';
import clsx from 'clsx';

import { Divider } from '../Divider';
import { Icon } from '../Icon';
import { Typography } from '../Typography';
import {
  accordionStyle,
  headerContainer,
  headerStyle,
  titleContainer,
  triggerStyle,
} from './Accordion.css';
import {
  AccordionContentProps,
  AccordionItemProps,
  AccordionRootProps,
  AccordionSize,
  AccordionTitleProps,
} from './Accordion.types';

type AccordionContextProps = {
  size: AccordionSize;
};

const AccordionContext = createContext<AccordionContextProps | undefined>(
  undefined,
);

export const Root = ({
  className,
  value,
  children,
  size = 'small',
  ...rest
}: AccordionRootProps) => {
  return (
    <AccordionContext.Provider value={useMemo(() => ({ size }), [size])}>
      <AccordionPrimitive.Root
        className={clsx(accordionStyle, className)}
        {...rest}
      >
        {children}
      </AccordionPrimitive.Root>
    </AccordionContext.Provider>
  );
};

export const Header = ({ icon, children }: AccordionTitleProps) => {
  const accordionContext = useContext(AccordionContext);
  const headerVariant = accordionContext?.size === 'small' ? 'h5' : 'h4';

  return (
    <div className={titleContainer}>
      {icon && <Icon icon={icon} size="medium" />}
      <Typography.Header variant={headerVariant} className={headerStyle}>
        {children}
      </Typography.Header>
    </div>
  );
};

export const Item = ({
  children,
  header,
  divider,
  className,
  ...rest
}: AccordionItemProps) => {
  const accordionContext = useContext(AccordionContext);
  const size = accordionContext?.size;
  const iconSize = size === 'small' ? 'small' : 'medium';

  return (
    <AccordionPrimitive.Item className={className} {...rest}>
      <AccordionPrimitive.Header asChild data-testid="accordionHeader">
        <div className={headerContainer({ size })}>
          {header}
          <AccordionPrimitive.Trigger
            className={triggerStyle}
            data-testid="accordionTrigger"
          >
            <Icon icon={ChevronDown} size={iconSize} />
          </AccordionPrimitive.Trigger>
        </div>
      </AccordionPrimitive.Header>
      {divider && <Divider orientation="horizontal" />}
      {children}
    </AccordionPrimitive.Item>
  );
};

export const Content: React.FC<AccordionContentProps> =
  AccordionPrimitive.Content;

export const Accordion = { Root, Item, Header, Content };
